```typescript
import { notionClient } from './client';
import { env } from '@/env';
import type { ProjectSummary, ProjectDetail } from '@/types/project';

// Notion Database 전체 프로젝트 조회 (커서 페이지네이션 지원)
export async function getProjects(): Promise<ProjectSummary[]> {
  let results = [];
  let cursor: string | undefined;

  do {
    const response = await notionClient.databases.query({
      database_id: env.NOTION_DATABASE_ID,
      start_cursor: cursor,
    });
    results.push(...response.results);
    cursor = response.next_cursor ?? undefined;
  } while (cursor);

  return results.map(mapPageToProjectSummary);
}

// 특정 프로젝트 상세 조회
export async function getProjectById(id: string): Promise<ProjectDetail | null> {
  try {
    const page = await notionClient.pages.retrieve({ page_id: id });
    const blocks = await getProjectBlocks(id);
    return mapPageToProjectDetail(page, blocks);
  } catch (error) {
    if (error.code === 'object_not_found') return null;
    throw error;
  }
}

// 프로젝트 본문 블록 조회
export async function getProjectBlocks(pageId: string) {
  let results = [];
  let cursor: string | undefined;

  do {
    const response = await notionClient.blocks.children.list({
      block_id: pageId,
      start_cursor: cursor,
    });
    results.push(...response.results);
    cursor = response.next_cursor ?? undefined;
  } while (cursor);

  return results;
}

// Notion Page → ProjectSummary 매핑
function mapPageToProjectSummary(page: any): ProjectSummary { /* ... */ }

// Notion Page + Blocks → ProjectDetail 매핑
function mapPageToProjectDetail(page: any, blocks: any[]): ProjectDetail { /* ... */ }
