import { notFound } from 'next/navigation';
import { getProjectById, getProjects } from '@/lib/notion/api';
import { BlockRenderer } from '@/components/notion/block-renderer';
import { ProjectLinks } from '@/components/projects/project-links';
import { TechStackBadges } from '@/components/projects/tech-stack-badges';

interface PageProps {
  params: Promise<{ id: string }>; // Next.js 16 비동기 params
}

export async function generateStaticParams() {
  const projects = await getProjects();
  return projects.map(p => ({ id: p.id }));
}

export async function generateMetadata({ params }: PageProps) {
  const { id } = await params;
  const project = await getProjectById(id);
  if (!project) return {};

  return {
    title: project.title,
    description: project.summary,
    openGraph: {
      title: project.title,
      description: project.summary,
      images: project.thumbnail ? [project.thumbnail] : [],
    },
  };
}

export default async function ProjectDetailPage({ params }: PageProps) {
  const { id } = await params;
  const project = await getProjectById(id);

  if (!project) notFound();

  return (
    <div className="mx-auto max-w-4xl px-4 py-12">
      {/* 썸네일, 제목, 기간 */}
      {/* 기술스택 뱃지 */}
      {/* GitHub/데모 링크 버튼 */}
      {/* Notion 본문 렌더링 */}
      <BlockRenderer blocks={project.blocks} />
    </div>
  );
}
