2. `src/lib/utils/sort.ts` 생성:
```typescript
import type { ProjectSummary } from '@/types/project';

export function sortProjectsByPeriod(projects: ProjectSummary[]): ProjectSummary[] {
  return [...projects].sort((a, b) => {
    const aStart = a.period.start ? new Date(a.period.start).getTime() : 0;
    const bStart = b.period.start ? new Date(b.period.start).getTime() : 0;
    return bStart - aStart; // 최신순
  });
}
```

