2. `src/lib/utils/featured.ts` 생성:
```typescript
import type { ProjectSummary } from '@/types/project';
import { sortProjectsByPeriod } from './sort';

export function selectFeaturedProjects(
  projects: ProjectSummary[],
  limit = 3
): ProjectSummary[] {
  const featured = projects.filter(p => p.featured);

  if (featured.length > 0) {
    return sortProjectsByPeriod(featured).slice(0, limit);
  }

  // Fallback: 기간 최신순 상위 N개
  return sortProjectsByPeriod(projects).slice(0, limit);
}
```

